const data = $input.first().json;

// =====================================================
// HELPER FUNCTIONS
// =====================================================

function escapeHtml(value) {
  return String(value ?? "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#039;");
}


// =====================================================
// MARKDOWN → HTML
// =====================================================

function markdownToHtml(text) {

  if (!text) return "";

  let html = escapeHtml(text);

  // Bold
  html = html.replace(
    /\*\*(.*?)\*\*/g,
    "<strong>$1</strong>"
  );

  // Evidence references
  html = html.replace(
    /\[Evidence ([^\]]+)\]/g,
    `<span style="
      display:inline-block;
      background:#e8f5e9;
      color:#166534;
      padding:2px 7px;
      border-radius:10px;
      font-size:10px;
      font-weight:600;
      margin-left:3px;
      white-space:nowrap;
    ">Evidence $1</span>`
  );

  // Remove remaining markdown bullets
  html = html.replace(
    /^[-•]\s*/g,
    ""
  );

  return html;
}


// =====================================================
// CLEAN LINES
// =====================================================

function cleanLines(text) {

  if (!text) return [];

  return text
    .split(/\n+/)
    .map(line => line.trim())
    .filter(line => line.length > 0)
    .map(line => {

      // Remove markdown bullet
      line = line.replace(/^[-•]\s*/, "");

      // Remove accidental numbered prefixes
      line = line.replace(/^\d+[\.\)]\s*/, "");

      return line.trim();
    })
    .filter(Boolean);
}


// =====================================================
// GET RAG ADVISORY
// =====================================================

const advisory = data.advisory || "";


// =====================================================
// EXTRACT SECTIONS
// =====================================================

function getSection(start, end) {

  const upper = advisory.toUpperCase();

  const startIndex = upper.indexOf(start);

  if (startIndex === -1) {
    return "";
  }

  const contentStart = startIndex + start.length;

  const endIndex = end
    ? upper.indexOf(end, contentStart)
    : advisory.length;

  return advisory
    .substring(
      contentStart,
      endIndex === -1 ? advisory.length : endIndex
    )
    .trim();
}


const assessment = getSection(
  "### ASSESSMENT",
  "### RECOMMENDATIONS"
);

const recommendations = getSection(
  "### RECOMMENDATIONS",
  "### LIMITATIONS"
);

const limitations = getSection(
  "### LIMITATIONS",
  null
);


// =====================================================
// ASSESSMENT HTML
// =====================================================

function assessmentHtml(text) {

  const lines = cleanLines(text);

  if (!lines.length) {

    return `
      <div style="
        padding:12px 0;
        color:#64748b;
        font-size:13px;
      ">
        No assessment available.
      </div>
    `;
  }

  return lines.map(line => {

    return `
      <div style="
        padding:7px 0;
        color:#334155;
        font-size:13px;
        line-height:1.55;
      ">
        ${markdownToHtml(line)}
      </div>
    `;

  }).join("");
}


// =====================================================
// RECOMMENDATION HTML
// =====================================================

function recommendationHtml(text) {

