            color:#64748b;
            font-size:10px;
            font-weight:700;
            text-transform:uppercase;
          "
        >
          Recommendation
        </td>

      </tr>


      ${lines.map((line, index) => `

        <tr>

          <!-- NUMBER -->

          <td
            width="42"
            valign="top"
            align="center"
            style="
              padding:10px 8px 10px 0;
              border-top:1px solid #e2e8f0;
            "
          >

            <div style="
              width:28px;
              height:28px;
              line-height:28px;
              border-radius:50%;
              background:#dcfce7;
              color:#166534;
              font-size:11px;
              font-weight:700;
              text-align:center;
            ">
              ${String(index + 1).padStart(2, "0")}
            </div>

          </td>


          <!-- TEXT -->

          <td
            valign="top"
            style="
              padding:10px 4px 10px 8px;
              border-top:1px solid #e2e8f0;
              color:#334155;
              font-size:13px;
              line-height:1.55;
            "
          >

            ${markdownToHtml(line)}

          </td>

        </tr>

      `).join("")}

    </table>

  `;
}


// =====================================================
// LIMITATIONS HTML
// =====================================================

function limitationHtml(text) {

  const lines = cleanLines(text);

  if (!lines.length) {

    return `
      <div style="
        padding:12px 0;
        color:#64748b;
        font-size:13px;
      ">
        No limitations available.
      </div>
    `;
  }

  return lines.map(line => {

    return `
      <div style="
        padding:9px 11px;
        margin-bottom:8px;
        background:#fffbeb;
        border:1px solid #fde68a;
        border-radius:8px;
        color:#78350f;
        font-size:12px;
        line-height:1.5;
      ">
        ⚠️ ${markdownToHtml(line)}
      </div>
    `;

  }).join("");
}


// =====================================================
