// Temperature
const temperature = escapeHtml(
  weather.temperature ??
  data.temperature ??
  "—"
);


// ET0
const et0 = escapeHtml(
  weather.et0 ??
  data.et0 ??
  "—"
);


// Rainfall
const rainfall = escapeHtml(
  weather.rainfall ??
  data.rainfall ??
  "—"
);


// Rain probability
const rainProbability = escapeHtml(
  weather.rain_probability ??
  data.rain_probability ??
  "—"
);


// =====================================================
